<style>
:root{--ink:#26332f;--muted:#7b827b;--paper:#f6f5ee;--line:#dcdfd4;--orange:#e96537;--green:#53705c}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px Arial,Helvetica,sans-serif}button,input{font:inherit}button{cursor:pointer}header{height:88px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 38px}.brand{display:flex;align-items:center;gap:13px}.mark{width:31px;height:31px;background:var(--orange);display:grid;place-items:center;color:#fff;font-size:26px;font-weight:normal}h1{font-size:23px;letter-spacing:-1px;margin:0;font-weight:600}.topnote,.eyebrow{font:10px '"'Courier New',monospace;letter-spacing:1.7px;text-transform:uppercase}.topnote{color:var(--muted)}.live{display:flex;gap:8px;align-items:center;font:11px 'Courier New',monospace}.dot{width:6px;height:6px;background:#78946b;border-radius:50%}main{max-width:1660px;margin:auto;padding:36px 38px 20px}.intro{display:flex;justify-content:space-between;align-items:end;margin-bottom:25px}.eyebrow{color:var(--orange);margin-bottom:13px}h2{font-size:33px;font-weight:500;letter-spacing:-1.3px;margin:0 0 9px}.intro p{margin:0;color:var(--muted);font-size:13px}.experiment-id{font:11px 'Courier New',monospace;color:var(--muted);padding-bottom:4px}.workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;border:1px solid var(--line);border-radius:9px;overflow:hidden;background:#fcfcf7}.left{min-width:0;border-right:1px solid var(--line)}.viewport{position:relative;height:clamp(340px,47vh,600px);background:#eff1e8;overflow:hidden}.viewtop{position:absolute;top:22px;left:24px;right:24px;display:flex;justify-content:space-between;pointer-events:none;z-index:1;font:10px 'Courier New',monospace;letter-spacing:1px}.viewtag{border:1px solid #cbd2c5;border-radius:4px;padding:7px 9px;background:#f7f8efb5;color:#58685a}.viewtop span:last-child{color:#8c988b;padding-top:8px}canvas{width:100%;height:100%;display:block}.viewbottom{position:absolute;bottom:15px;left:24px;right:24px;display:flex;justify-content:space-between;align-items:center;font:10px 'Courier New',monospace;color:#7d887c;pointer-events:none}.scale{display:flex;align-items:center;gap:10px}.scale i{display:block;width:45px;height:6px;border:1px solid #83907e;border-top:0}.telemetry{display:grid;grid-template-columns:repeat(3,1fr);padding:22px 0;border-top:1px solid var(--line);background:#fafbf5}.metric{padding:0 24px;border-right:1px solid var(--line)}.metric:last-child{border:0}.metric label{display:block;color:var(--muted);font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:9px}.metric strong{font:27px 'Courier New',monospace;letter-spacing:-1px;font-weight:400}.metric small{font:11px 'Courier New',monospace;color:#93998d;margin-left:5px}.controls{padding:24px;background:#f9faf3}.paneltitle{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.paneltitle h3{font-size:14px;margin:0;font-weight:600}.paneltitle span{color:#929c8d;font-size:17px}.setting{margin-bottom:23px}.setting label{display:flex;justify-content:space-between;align-items:center;font-size:12px;margin-bottom:12px}.value{font:12px 'Courier New',monospace;background:#edf0e5;padding:4px 7px;border-radius:3px;color:#51644e}.setting input{appearance:none;width:100%;height:3px;background:linear-gradient(to right,var(--green) 42%,#dfe4d6 42%);outline:none;display:block;margin:0;cursor:pointer}.setting input::-webkit-slider-thumb{appearance:none;background:#fcfcf6;width:12px;height:12px;border:2px solid #61765a;border-radius:50%}.setting input::-moz-range-thumb{background:#fcfcf6;width:9px;height:9px;border:2px solid #61765a;border-radius:50%}.limits{display:flex;justify-content:space-between;color:#9ba18f;font:9px 'Courier New',monospace;margin-top:9px}.actions{border-top:1px solid var(--line);padding-top:20px;display:flex;gap:8px}.test{flex:1;background:var(--orange);color:white;border:1px solid var(--orange);border-radius:4px;padding:12px;font-size:12px;font-weight:600}.test:hover{background:#d9562c}.reset{background:transparent;border:1px solid #d6dccb;border-radius:4px;padding:0 14px;color:#63715d}.reset:hover{background:#edf0e5}.hint{font:10px/1.6 'Courier New',monospace;color:#909985;margin:12px 0 0}.details{margin-top:22px;display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px}.detail{padding:17px 0;border-top:1px solid var(--line)}.detail label{display:block;font:10px 'Courier New',monospace;letter-spacing:1px;color:#8c9385;text-transform:uppercase;margin-bottom:9px}.detail p{margin:0;font-size:11px;line-height:1.8;color:#66715f}.detail b{font-weight:400;color:#354331}.footer{border-top:1px solid var(--line);margin-top:12px;padding:16px 0;display:flex;justify-content:space-between;font:9px 'Courier New',monospace;color:#949c8f;letter-spacing:.5px}button:focus-visible,input:focus-visible{outline:2px solid var(--orange);outline-offset:5px}@media(max-width:850px){header{padding:0 20px;height:70px}.topnote{display:none}main{padding:25px 18px}.workspace{grid-template-columns:1fr}.left{border-right:0}.controls{border-top:1px solid var(--line);display:grid;grid-template-columns:1fr 1fr;gap:0 25px}.paneltitle,.actions,.hint{grid-column:1/-1}.paneltitle{margin-bottom:22px}.viewport{height:380px}.details{gap:15px}h2{font-size:28px}.experiment-id{display:none}.metric{padding:0 16px}.metric strong{font-size:23px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}
</style>
</head>
<body>
<header><div class=\"brand\"><div class=\"mark\" aria-hidden=\"true\">✳</div><h1>GPT-6</h1></div><div class=\"topnote\">Independent experiments / rigid body dynamics</div><div class=\"live\"><i class=\"dot\"></i> SYSTEM READY</div></header>
<main><div class=\"intro\"><div><div class=\"eyebrow\">Experiment 001 · Impact dynamics</div><h2>A collision. Every brick counts.</h2><p>Change the conditions. Launch the car. See what holds up.</p></div><div class=\"experiment-id\">2D TEST ENVIRONMENT ↗</div></div>
<div class=\"workspace\"><div class=\"left\"><div class=\"viewport\"><div class=\"viewtop\"><div class=\"viewtag\" id=\"status\">● READY TO TEST</div><span>SIDE ELEVATION / LIVE</span></div><canvas id=\"scene\" aria-label=\"Side view of a car and a wall of individual physical bricks\"></canvas><div class=\"viewbottom\"><div class=\"scale\"><i></i><span id=\"scaleLabel\">1 M</span></div><span id=\"sceneInfo\">192 RIGID BRICKS · 2 LAYERS</span></div></div><div class=\"telemetry\"><div class=\"metric\"><label>Car velocity</label><strong id=\"velocity\">0.0</strong><small>m/s</small></div><div class=\"metric\"><label>Elapsed time</label><strong id=\"elapsed\">0.00</strong><small>s</small></div><div class=\"metric\"><label>Moving bricks</label><strong id=\"moving\">0</strong><small id=\"total\">/ 192</small></div></div></div>
<aside class=\"controls\" aria-label=\"Experiment settings\"><div class=\"paneltitle\"><h3>Experiment settings</h3><span aria-hidden=\"true\">☷</span></div>
<div class=\"setting\"><label for=\"speed\">Car speed <output class=\"value\" id=\"speedValue\">22 m/s</output></label><input id=\"speed\" type=\"range\" min=\"5\" max=\"45\" step=\"1\" value=\"22\"><div class=\"limits\"><span>5 m/s</span><span>45 m/s</span></div></div>
<div class=\"setting\"><label for=\"cols\">Wall columns <output class=\"value\" id=\"colsValue\">12</output></label><input id=\"cols\" type=\"range\" min=\"4\" max=\"24\" step=\"1\" value=\"12\"><div class=\"limits\"><span>4 bricks</span><span>24 bricks</span></div></div>
<div class=\"setting\"><label for=\"rows\">Wall rows <output class=\"value\" id=\"rowsValue\">8</output></label><input id=\"rows\" type=\"range\" min=\"3\" max=\"16\" step=\"1\" value=\"8\"><div class=\"limits\"><span>3 bricks</span><span>16 bricks</span></div></div>
<div class=\"setting\"><label for=\"layers\">Depth layers <output class=\"value\" id=\"layersValue\">2</output></label><input id=\"layers\" type=\"range\" min=\"1\" max=\"5\" step=\"1\" value=\"2\"><div class=\"limits\"><span>1 layer</span><span>5 layers</span></div></div>
<div class=\"setting\"><label for=\"mass\">Brick mass <output class=\"value\" id=\"massValue\">2.5 kg</output></label><input id=\"mass\" type=\"range\" min=\"0.5\" max=\"12\" step=\"0.5\" value=\"2.5\"><div class=\"limits\"><span>0.5 kg</span><span>12 kg</span></div></div>
<div class=\"actions\"><button class=\"test\" id=\"test\">▶ &nbsp; Test</button><button class=\"reset\" id=\"reset\" aria-label=\"Reset experiment\">↺ &nbsp; Reset</button></div><p class=\"hint\" id=\"hint\">Fixed timestep. Same inputs, same outcome.<br>Space to test · R to reset</p></aside></div>
<div class=\"details\"><div class=\"detail\"><label>01 / The vehicle</label><p><b>1,250 kg</b> · 4.20 × 1.45 m<br>Powered run-up. Free response on impact.</p></div><div class=\"detail\"><label>02 / The material</label><p><b>0.50 × 0.24 m</b> clay bricks · staggered bond<br>Friction 0.72 · restitution 0.18</p></div><div class=\"detail\"><label>03 / The conditions</label><p><b>9.81 m/s²</b> gravity · ground friction 0.85<br>80 px/m reference · adaptive view</p></div></div><div class=\"footer\"><span>NO SCRIPTED COLLAPSE. JUST MOMENTUM.</span><span>SI UNITS / DETERMINISTIC SOLVER</span></div>
</main>
<script>
'use strict';
/* Self-contained rigid body engine. SI units; y points down. Layers are independent
   2D contact planes connected by a single shared vehicle. No random physics. */
const G=9.81,DT=1/240,ITERATIONS=14;
const canvas=document.getElementById('scene'),ctx=canvas.getContext('2d');
const settings={speed:22,cols:12,rows:8,layers:2,mass:2.5};
let bodies=[],bricks=[],car,cache=new Map(),running=false,impacted=false,time=0,accumulator=0,lastFrame=0,impactTime=0,quietTime=0,dust=[],peak=0;
let view={w:0,h:0,scale:80,ox:0,ground:0};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function body(id,x,y,w,h,m,layer){return {id,x,y,w,h,hx:w/2,hy:h/2,m,im:1/m,ii:12/(m*(w*w+h*h)),vx:0,vy:0,a:0,av:0,layer,c:1,s:0,r:Math.hypot(w,h)/2};}
function geometry(b){b.c=Math.cos(b.a);b.s=Math.sin(b.a);b.ex=Math.abs(b.c)*b.hx+Math.abs(b.s)*b.hy;b.ey=Math.abs(b.s)*b.hx+Math.abs(b.c)*b.hy;}
function vertices(b){return [[-b.hx,-b.hy],[b.hx,-b.hy],[b.hx,b.hy],[-b.hx,b.hy]].map(([x,y])=>({x:b.x+b.c*x-b.s*y,y:b.y+b.s*x+b.c*y}));}
function clip(points,tx,ty,bound,sign){if(points.length<2)return [];const d0=sign*(points[0].x*tx+points[0].y*ty-bound),d1=sign*(points[1].x*tx+points[1].y*ty-bound);const out=[];if(d0<=0)out.push(points[0]);if(d1<=0)out.push(points[1]);if(d0*d1<0){const t=d0/(d0-d1);out.push({x:points[0].x+t*(points[1].x-points[0].x),y:points[0].y+t*(points[1].y-points[0].y)});}return out.slice(0,2);}
function collide(a,b){
 const dx=b.x-a.x,dy=b.y-a.y;if(Math.abs(dx)>a.ex+b.ex+.002||Math.abs(dy)>a.ey+b.ey+.002)return null;
 const axes=[[a.c,a.s,a,0],[-a.s,a.c,a,1],[b.c,b.s,b,0],[-b.s,b.c,b,1]];let overlap=Infinity,best=null;
 for(const axis of axes){const [nx,ny]=axis;const ra=a.hx*Math.abs(nx*a.c+ny*a.s)+a.hy*Math.abs(-nx*a.s+ny*a.c),rb=b.hx*Math.abs(nx*b.c+ny*b.s)+b.hy*Math.abs(-nx*b.s+ny*b.c);const p=ra+rb-Math.abs(dx*nx+dy*ny);if(p<-.001)return null;if(p<overlap){overlap=p;best=axis;}}
 let nx=best[0],ny=best[1];if(dx*nx+dy*ny<0){nx=-nx;ny=-ny;}
 const ref=best[2],inc=ref===a?b:a,rnx=ref===a?nx:-nx,rny=ref===a?ny:-ny;
 const half=best[3]===0?ref.hx:ref.hy,side=best[3]===0?ref.hy:ref.hx;
 const fx=ref.x+rnx*half,fy=ref.y+rny*half,tx=-rny,ty=rnx;
 const normals=[[inc.c,inc.s,inc.hx,inc.hy],[-inc.c,-inc.s,inc.hx,inc.hy],[-inc.s,inc.c,inc.hy,inc.hx],[inc.s,-inc.c,inc.hy,inc.hx]];
 let face=normals[0];for(const n of normals)if(n[0]*rnx+n[1]*rny<face[0]*rnx+face[1]*rny)face=n;
 const ix=inc.x+face[0]*face[2],iy=inc.y+face[1]*face[2],itx=-face[1],ity=face[0];
 let pts=[{x:ix+itx*face[3],y:iy+ity*face[3]},{x:ix-itx*face[3],y:iy-ity*face[3]}];const center=fx*tx+fy*ty;
 pts=clip(pts,tx,ty,center+side,1);pts=clip(pts,tx,ty,center-side,-1);
 pts=pts.map(p=>{const depth=(fx-p.x)*rnx+(fy-p.y)*rny;return {x:p.x+rnx*depth*.5,y:p.y+rny*depth*.5,depth};}).filter(p=>p.depth>=-.002);
 pts.sort((p,q)=>(p.x-q.x)*(-ny)+(p.y-q.y)*nx);return pts.length?{a,b,nx,ny,pts}:null;
}
function groundContact(b){if(b.y+b.ey<-.002)return null;const pts=vertices(b).filter(p=>p.y>=-.002).sort((p,q)=>p.x-q.x);if("'!pts.length)return null;return {a:b,b:null,nx:0,ny:1,pts:(pts.length>2?[pts[0],pts[pts.length-1]]:pts).map(p=>({x:p.x,y:p.y/2,depth:p.y}))};}
function impulse(c,jx,jy){const a=c.a,b=c.b;a.vx-=jx*a.im;a.vy-=jy*a.im;a.av-=(c.rax*jy-c.ray*jx)*a.ii;if(b){b.vx+=jx*b.im;b.vy+=jy*b.im;b.av+=(c.rbx*jy-c.rby*jx)*b.ii;}}
function relative(c){const a=c.a,b=c.b;return {x:(b?b.vx-b.av*c.rby:0)-(a.vx-a.av*c.ray),y:(b?b.vy+b.av*c.rbx:0)-(a.vy+a.av*c.rax)};}
function makeConstraints(manifolds){const result=[];for(const m of manifolds){const a=m.a,b=m.b;for(let i=0;i<m.pts.length;i++){const p=m.pts[i],nx=m.nx,ny=m.ny,tx=-ny,ty=nx;
 const c={a,b,nx,ny,tx,ty,rax:p.x-a.x,ray:p.y-a.y,rbx:b?p.x-b.x:0,rby:b?p.y-b.y:0,key:a.id+'"':'+(b?b.id:'g')+':'+i};
 const im=a.im+(b?b.im:0),an=c.rax*ny-c.ray*nx,bn=c.rbx*ny-c.rby*nx,at=c.rax*ty-c.ray*tx,bt=c.rbx*ty-c.rby*tx;
 c.mn=1/(im+an*an*a.ii+(b?bn*bn*b.ii:0));c.mt=1/(im+at*at*a.ii+(b?bt*bt*b.ii:0));
 const rv=relative(c),vn=rv.x*nx+rv.y*ny;c.bias=Math.min(3,.16/DT*Math.max(0,p.depth-.0015))+ (vn < -1 ? -.18*vn:0);
 c.mu=b?.72:(a===car&&"'!impacted?.012:Math.sqrt(.72*.85));const old=cache.get(c.key);c.jn=old&&old.nx*nx+old.ny*ny>.95?old.jn*.85:0;c.jt=old?clamp(old.jt*.85,-c.mu*c.jn,c.mu*c.jn):0;result.push(c);
 }}return result;}
function broadphase(){const map=new Map(),pairs=[],seen=new Set();for(const b of bricks){const x0=Math.floor((b.x-b.ex)/.6),x1=Math.floor((b.x+b.ex)/.6),y0=Math.floor((b.y-b.ey)/.6),y1=Math.floor((b.y+b.ey)/.6);for(let x=x0;x<=x1;x++)for(let y=y0;y<=y1;y++){const key=b.layer+'"','+x+','+y;let cell=map.get(key);if("'!cell){cell=[];map.set(key,cell);}for(const a of cell){const pk=a.id*4096+b.id;if(!seen.has(pk)){seen.add(pk);pairs.push([a,b]);}}cell.push(b);}}
 for(const b of bricks)if(Math.abs(b.x-car.x)<b.ex+car.ex+.002&&Math.abs(b.y-car.y)<b.ey+car.ey+.002)pairs.push([car,b]);return pairs;}
function step(){
 if(!impacted){const acceleration=settings.speed*settings.speed/(2*7.5);car.vx=Math.min(settings.speed,car.vx+acceleration*DT);}
 for(const b of bodies){b.vy+=G*DT;geometry(b);}
 const manifolds=[];for(const b of bodies){const m=groundContact(b);if(m)manifolds.push(m);}
 for(const [a,b] of broadphase()){const m=collide(a,b);if(m){manifolds.push(m);if(a===car&&!impacted){impacted=true;impactTime=time;makeDust();}}}
 const cs=makeConstraints(manifolds);for(const c of cs)impulse(c,c.nx*c.jn+c.tx*c.jt,c.ny*c.jn+c.ty*c.jt);
 for(let iter=0;iter<ITERATIONS;iter++)for(const c of cs){let rv=relative(c),jn=c.mn*(c.bias-rv.x*c.nx-rv.y*c.ny),old=c.jn;c.jn=Math.max(0,old+jn);jn=c.jn-old;impulse(c,c.nx*jn,c.ny*jn);rv=relative(c);let jt=-c.mt*(rv.x*c.tx+rv.y*c.ty);old=c.jt;c.jt=clamp(old+jt,-c.mu*c.jn,c.mu*c.jn);jt=c.jt-old;impulse(c,c.tx*jt,c.ty*jt);}
 cache=new Map(cs.map(c=>[c.key,{jn:c.jn,jt:c.jt,nx:c.nx,ny:c.ny}]));
 for(const b of bodies){b.x+=b.vx*DT;b.y+=b.vy*DT;b.a+=b.av*DT;}
 time+=DT;peak=Math.max(peak,car.vx);const moving=bricks.reduce((n,b)=>n+(Math.hypot(b.vx,b.vy)>.12||Math.abs(b.av)>.3),0);
 if(impacted&&moving===0&&Math.hypot(car.vx,car.vy)<.1)quietTime+=DT;else quietTime=0;
 if(quietTime>1.5||time>=20){running=false;setStatus(time>=20?'"'● TEST COMPLETE · 20 S':'● DEBRIS SETTLED');}
}
function reset(){running=false;impacted=false;time=0;impactTime=0;quietTime=0;accumulator=0;peak=0;dust=[];cache.clear();bricks=[];
 car=body(0,-10,-.725,4.2,1.45,1250,-1);let id=1;
 for(let l=0;l<settings.layers;l++)for(let r=0;r<settings.rows;r++)for(let c=0;c<settings.cols;c++){const b=body(id++,.25+c*.5+(r%2)*.25,-.12-r*.24,.5,.24,settings.mass,l);b.row=r;b.col=c;b.originalX=b.x;b.originalY=b.y;bricks.push(b);}
 bodies=[car,...bricks];for(const b of bodies)geometry(b);fitView();setStatus('● READY TO TEST');document.getElementById('sceneInfo').textContent=bricks.length+' RIGID BRICKS · '+settings.layers+' LAYER'+(settings.layers>1?'S':'');document.getElementById('total').textContent='/ '+bricks.length;updateTelemetry();render();}
function start(){reset();running=true;setStatus('● RUNNING · ACCELERATING');}
function setStatus(text){document.getElementById('status').textContent=text;}
function makeDust(){for(let i=0;i<38;i++){const f=(i*.61803398875)%1;dust.push({x:0,y:-.1-(i%7)*.16,vx:1+f*4,vy:-1-((i*.37)%1)*3,r:.06+((i*.43)%1)*.12});}setStatus('● IMPACT · LIVE PHYSICS');}
function fitView(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);view.w=rect.width;view.h=rect.height;canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);const extent=settings.cols*.5+4;view.scale=Math.min(80,(view.w-95)/(extent+13),(view.h-130)/(settings.rows*.24+1));view.ox=45+12.5*view.scale;view.ground=view.h*.73;document.querySelector('.scale i').style.width=view.scale+'px';}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
function render(){if("'!car)return;const {w,h,scale:s,ox,ground}=view;ctx.clearRect(0,0,w,h);ctx.fillStyle='"'#eff1e8';ctx.fillRect(0,0,w,h);
 let camera=0;if(impacted&&car.x>settings.cols*.5+2)camera=Math.min(car.x-(settings.cols*.5+2),25)*s;
 const shock=impacted?Math.max(0,1-(time-impactTime)/.35):0;const shake=shock*Math.sin(time*190)*2;
 ctx.save();ctx.translate(shake,Math.cos(time*153)*shock);ctx.translate(-camera,0);
 ctx.strokeStyle='#e2e7db';ctx.lineWidth=.65;for(let x=ox% (s*2);x<w+camera+50;x+=s*2){ctx.beginPath();ctx.moveTo(x,70);ctx.lineTo(x,ground);ctx.stroke();}for(let y=ground;y>70;y-=s){ctx.beginPath();ctx.moveTo(camera,y);ctx.lineTo(w+camera,y);ctx.stroke();}
 // A quiet, schematic horizon.
 ctx.strokeStyle='#d7dfd0';ctx.beginPath();ctx.moveTo(camera,ground-20);ctx.lineTo(w+camera,ground-20);ctx.stroke();ctx.fillStyle='#e3e7da';ctx.fillRect(camera,ground,w, h-ground);ctx.fillStyle='#b2bda6';ctx.fillRect(camera,ground,w,2);
 ctx.font='9px Courier New';ctx.textAlign='center';for(let m=-12;m<settings.cols*.5+40;m+=2){const x=ox+m*s;ctx.strokeStyle='#bec7b3';ctx.beginPath();ctx.moveTo(x,ground+4);ctx.lineTo(x,ground+10);ctx.stroke();ctx.fillStyle='#8c9881';ctx.fillText(m+' m',x,ground+25);}
 if(impacted){ctx.strokeStyle='#79826d55';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(ox+(-1.4)*s,ground+2);ctx.lineTo(ox+car.x*s,ground+2);ctx.stroke();}
